use std :: fs ; use std :: path :: Path ; use regex :: Regex ; use std :: collections :: HashSet ; fn scan_directory (dir : & Path , regex : & Regex , refs : & mut HashSet < String >) { if ! dir . is_dir () { return ; } if let Ok (entries) = fs :: read_dir (dir) { for entry in entries . flatten () { let path = entry . path () ; let name = entry . file_name () . to_string_lossy () . to_string () ; if name == ".git" || name . starts_with ('.') { continue ; } if path . is_dir () { if path . join ("Cargo.toml") . exists () { scan_cargo_toml (& path , regex , refs) ; } scan_directory (& path , regex , refs) ; } } } }